502	    private <T> T findEntityById(Supplier<T> supplier) {
503	        try {
504	            return supplier.get();
505	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
506	            // Just ignore not found exceptions for Jdbc/Jpa realization
507	            return null;
508	        }
509	    }
